const item = $input.first().json;
const body = item.body || item;

const nama = body.nama_pelanggan || '';
const noHp = body.no_hp || '';
const email = body.email || '';
const kategori = body.kategori_keluhan || 'Lainnya';
const deskripsi = body.deskripsi || '';
const nomorPesanan = body.nomor_pesanan || '-';

// Generate ticket number: TKT/YYYYMMDD/XXX
const now = new Date();
const y = now.getFullYear();
const m = String(now.getMonth() + 1).padStart(2, '0');
const d = String(now.getDate()).padStart(2, '0');
const seq = String(Math.floor(Math.random() * 900) + 100);
const nomorTiket = `TKT/${y}${m}${d}/${seq}`;

// Classify priority based on keywords
const lower = deskripsi.toLowerCase();
let prioritas = 'rendah';
let sla = '3 hari kerja';

const keywordTinggi = ['rusak', 'tidak berfungsi', 'penting', 'urgent', 'bahaya', 'error fatal', 'tidak bisa digunakan', 'cacat', 'berbahaya'];
const keywordSedang = ['lambat', 'kurang', 'terlambat', 'belum sampai', 'salah kirim', 'tidak sesuai', 'kurang lengkap'];

if (keywordTinggi.some(kw => lower.includes(kw))) {
  prioritas = 'tinggi';
  sla = '4 jam';
} else if (keywordSedang.some(kw => lower.includes(kw))) {
  prioritas = 'sedang';
  sla = '1 hari kerja';
}

const timestamp = now.toLocaleString('id-ID', {
  timeZone: 'Asia/Jakarta',
  day: '2-digit', month: 'long', year: 'numeric',
  hour: '2-digit', minute: '2-digit'
});

return [{
  json: {
    nomor_tiket: nomorTiket,
    nama_pelanggan: nama,
    no_hp: noHp,
    email: email,
    kategori_keluhan: kategori,
    deskripsi: deskripsi,
    nomor_pesanan: nomorPesanan,
    prioritas: prioritas,
    sla: sla,
    status: 'Baru',
    tanggal_masuk: timestamp,
    tanggal_iso: now.toISOString()
  }
}];

